// Usage: saxpy <out.bin> [n=1048576]
#include <sycl/sycl.hpp>
#include <cstdio>
#include <cstdlib>

int main(int argc, char** argv) {
  if (argc < 2) {
    std::fprintf(stderr, "usage: %s out.bin [n]\n", argv[0]);
    return 2;
  }
  const int n = argc > 2 ? std::atoi(argv[2]) : (1 << 20);
  const float a = 2.5f;

  sycl::queue q{sycl::gpu_selector_v, sycl::property::queue::enable_profiling{}};
  // Fall back to the default device if no GPU is present.
  // (sycl::queue q{...} above throws if no GPU; see try/catch below.)

  float* x = sycl::malloc_shared<float>(n, q);
  float* y = sycl::malloc_shared<float>(n, q);
  if (!x || !y) {
    std::fprintf(stderr, "allocation failed\n");
    return 1;
  }
  for (int i = 0; i < n; ++i) {
    x[i] = static_cast<float>(i % 1000) * 0.001f;
    y[i] = static_cast<float>((i * 7) % 1000) * 0.002f;
  }

  const std::size_t local = 256;
  const std::size_t global = ((static_cast<std::size_t>(n) + local - 1) / local) * local;
  sycl::event ev = q.parallel_for(
      sycl::nd_range<1>{sycl::range<1>{global}, sycl::range<1>{local}},
      [=](sycl::nd_item<1> it) {
        const std::size_t i = it.get_global_id(0);
        if (i < static_cast<std::size_t>(n)) y[i] = a * x[i] + y[i];
      });

  try {
    q.wait_and_throw();
  } catch (const sycl::exception& e) {
    std::fprintf(stderr, "SYCL error: %s\n", e.what());
    return 1;
  }

  const auto t0 = ev.get_profiling_info<sycl::info::event_profiling::command_start>();
  const auto t1 = ev.get_profiling_info<sycl::info::event_profiling::command_end>();
  const float ms = static_cast<float>(t1 - t0) * 1e-6f;
  std::printf("kernel_ms=%f\n", ms);

  FILE* f = std::fopen(argv[1], "wb");
  if (!f || std::fwrite(y, sizeof(float), n, f) != static_cast<size_t>(n)) return 1;
  std::fclose(f);

  sycl::free(x, q);
  sycl::free(y, q);
  return 0;
}

